   "// empleado: entrada, salida, horas, retardos y faltas (justificadas si hay\n// incidencia aprobada o vacaciones).\n\nlet ASIS = { desde: null, hasta: null, datos: null, abierto: null, filtro: '', vista: null, opciones: null };\nconst ASIS_DIAS = [['1', 'L'], ['2', 'M'], ['3', 'Mi'], ['4', 'J'], ['5', 'V'], ['6', 'S'], ['7', 'D']];\nconst ASIS_ESTATUS = {\n  puntual: ['Puntual', '#4caf50'], retardo: ['Retardo', '#e8a33d'], falta: ['Falta', '#D8192F'],\n"
